SELECT w.w_state, w.w_city, SUM(cr.cr_return_amount) AS total_return_amount, COUNT(ws.ws_order_number) AS order_count FROM catalog_returns cr JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk JOIN web_sales ws ON ws.ws_warehouse_sk = w.w_warehouse_sk WHERE w.w_state = 'TN' AND cr.cr_returned_date_sk >= 2451139 AND cr.cr_returned_date_sk <= 2451142 GROUP BY w.w_state, w.w_city
